-- Japanese catalog source: https://digimon.jsuk.cloud/data/digimon.js
-- Source snapshot verified and converted for the local 459-Digimon catalog on 2026-08-21.
CREATE TABLE digimon_stage_jp LIKE digimon_stage;
CREATE TABLE item_jp LIKE item_kr;
CREATE TABLE digimon_jp LIKE digimon_kr;
CREATE TABLE evolution_jp LIKE evolution_kr;
CREATE TABLE digimon_special_skill_jp LIKE digimon_special_skill_kr;
CREATE TABLE digimon_attachment_skill_jp LIKE digimon_attachment_skill_kr;

ALTER TABLE digimon_jp
    ADD CONSTRAINT fk_digimon_stage_jp FOREIGN KEY (stage_code) REFERENCES digimon_stage_jp(stage_code);
ALTER TABLE evolution_jp
    ADD CONSTRAINT fk_evolution_from_jp FOREIGN KEY (from_digimon_id) REFERENCES digimon_jp(id),
    ADD CONSTRAINT fk_evolution_to_jp FOREIGN KEY (to_digimon_id) REFERENCES digimon_jp(id),
    ADD CONSTRAINT fk_evolution_item_jp FOREIGN KEY (required_item_id) REFERENCES item_jp(id);
ALTER TABLE digimon_special_skill_jp
    ADD CONSTRAINT fk_special_skill_digimon_jp FOREIGN KEY (digimon_id) REFERENCES digimon_jp(id);
ALTER TABLE digimon_attachment_skill_jp
    ADD CONSTRAINT fk_attachment_skill_digimon_jp FOREIGN KEY (digimon_id) REFERENCES digimon_jp(id);

INSERT INTO digimon_stage_jp (stage_code, stage_name, sort_order) VALUES
    ('BABY_1', '幼年期Ⅰ', 10), ('BABY_2', '幼年期Ⅱ', 20),
    ('ROOKIE', '成長期', 30), ('CHAMPION', '成熟期', 40),
    ('ULTIMATE', '完全体', 50), ('MEGA', '究極体', 60),
    ('MEGA_PLUS', '超究極体', 70), ('ARMOR', 'アーマー体', 80),
    ('HYBRID', 'ハイブリッド体', 90);

INSERT INTO item_jp SELECT * FROM item_kr;
INSERT INTO digimon_jp SELECT * FROM digimon_kr;
INSERT INTO evolution_jp SELECT * FROM evolution_kr;
INSERT INTO digimon_special_skill_jp SELECT * FROM digimon_special_skill_kr;
INSERT INTO digimon_attachment_skill_jp SELECT * FROM digimon_attachment_skill_kr;

UPDATE digimon_jp SET source_url = REPLACE(source_url, 'reference_ko/', 'reference/');

UPDATE digimon_jp SET name = 'クラモン', attribute = 'NO DATA', digimon_type = '不明', personality = '悪知恵', evolution_condition = NULL WHERE (game_capture_url LIKE '%/kuramon.%' OR source_url LIKE '%directory_name=kuramon' OR name = '쿠라몬');
