UPDATE evolution_jp e
JOIN digimon_jp destination ON destination.id = e.to_digimon_id
SET e.condition_text = destination.evolution_condition;

UPDATE item_jp SET
    name = CASE id
        WHEN 1 THEN '知識のカプセル' WHEN 2 THEN '勇気のカプセル'
        WHEN 3 THEN '愛情のカプセル' WHEN 4 THEN '友情のカプセル'
        WHEN 5 THEN '光のカプセル' WHEN 6 THEN '希望のカプセル'
        WHEN 7 THEN '純真のカプセル' WHEN 8 THEN '誠実のカプセル'
        WHEN 9 THEN '奇跡のカプセル' WHEN 10 THEN '運命のカプセル'
        ELSE name END,
    description = 'アーマー進化に必要なカプセル';

